import os
from xml.dom import minidom

# List unpacked files
for root, dirs, files in os.walk("unpacked"):
    dirs[:] = [d for d in dirs if d != "__pycache__"]
    for f in files:
        print(os.path.join(root, f))

print("\n=== PARAGRAPHS ===")
doc = minidom.parse("unpacked/word/document.xml")
ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def qn(tag):
    return f"{{{ns}}}{tag}"

def text_of(p):
    parts = []
    for t in p.getElementsByTagName(qn("t")):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)

for p in doc.getElementsByTagName(qn("p")):
    pPr = p.getElementsByTagName(qn("pPr"))
    style = ""
    if pPr:
        pStyle = pPr[0].getElementsByTagName(qn("pStyle"))
        if pStyle:
            style = pStyle[0].getAttribute(qn("val"))
    txt = text_of(p)
    print(f"[{style or 'Normal'}] {txt!r}")

