import sys, re

sys.path.insert(0, ".codex/skills/docx")
from scripts.document import Document

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"

def para_text(p):
    return "".join(
        t.firstChild.nodeValue or ""
        for t in p.getElementsByTagName(W + "t")
    )

def is_headline(txt):
    if not txt:
        return False
    if txt.startswith("\u2022"):  # bullet
        return False
    # headline: short line entirely uppercase (letters only uppercase)
    letters = [c for c in txt if c.isalpha()]
    if not letters:
        return False
    if any(c.islower() for c in letters):
        return False
    return len(txt) <= 40

doc = Document("unpacked")
editor = doc["word/document.xml"]
paras = editor.dom.getElementsByTagName(W + "p")

matches = []
for p in paras:
    txt = para_text(p)
    if is_headline(txt):
        matches.append((p, txt))

print("HEADLINES DETECTED (%d):" % len(matches))
for _, txt in matches:
    print(" -", txt)

if "--apply" in sys.argv:
    for p, _ in matches:
        for r in p.getElementsByTagName(W + "r"):
            rPr = r.getElementsByTagName(W + "rPr")
            if rPr:
                rpr = rPr[0]
                # find insertion point per schema order: rFonts, sz, szCs, then u
                anchor = None
                for tag in (W + "szCs", W + "sz", W + "rFonts"):
                    els = rpr.getElementsByTagName(tag)
                    if els:
                        anchor = els[-1]
                if anchor is not None and anchor.nextSibling is not None:
                    anchor = anchor.nextSibling
                elif anchor is None:
                    anchor = rpr.firstChild
            else:
                rpr = doc.dom.createElementNS(
                    "http://schemas.openxmlformats.org/wordprocessingml/2006/main", "w:rPr"
                )
                r.insertBefore(rpr, r.firstChild)
                anchor = None
            u = doc.dom.createElementNS(
                "http://schemas.openxmlformats.org/wordprocessingml/2006/main", "w:u"
            )
            u.setAttributeNS(
                "http://schemas.openxmlformats.org/wordprocessingml/2006/main",
                "w:val", "single"
            )
            if anchor is not None:
                rpr.insertBefore(u, anchor)
            else:
                rpr.appendChild(u)
    doc.save()
    print("APPLIED: underline added to runs in %d headline paragraphs" % len(matches))
else:
    print("DRY RUN - no changes made")

